import { test, expect } from '@playwright/test';

test.describe('Profile Settings - Language Preference', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully set language preference and display selected language', async ({ page }) => {
    // Verify language selection dropdown is visible
    const languageDropdown = page.getByRole('combobox', { name: /language/i });
    await expect(languageDropdown).toBeVisible();

    // Verify default language is selected
    const defaultLanguageLabel = page.getByText(/default/i);
    await expect(defaultLanguageLabel).toBeVisible();

    // Verify language options are available
    const spanCount = page.locator('[data-testid="language-option-count"]').count();
    expect(spanCount).toBeGreaterThan(0);

    // Set language preference to Spanish
    const spanishOption = page.getByRole('option', { name: /spanish/i });
    await expect(spanishOption).toBeVisible();
    await spanishOption.click();

    // Verify language preference is set
    const selectedLanguageLabel = page.getByText(/español/i);
    await expect(selectedLanguageLabel).toBeVisible();

    // Verify language is applied to the page
    const pageLanguage = page.getByTestId('page-language');
    await expect(pageLanguage).toContainText('español');

    // Verify language preference is saved
    const settingsButton = page.getByRole('button', { name: /save settings/i });
    await expect(settingsButton).toBeVisible();
    await settingsButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/language preference saved/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle invalid language input and display error message', async ({ page }) => {
    // Verify language dropdown is visible
    const languageDropdown = page.getByRole('combobox', { name: /language/i });
    await expect(languageDropdown).toBeVisible();

    // Verify default language is selected
    const defaultLanguageLabel = page.getByText(/default/i);
    await expect(defaultLanguageLabel).toBeVisible();

    // Verify language options are available
    const spanCount = page.locator('[data-testid="language-option-count"]').count();
    expect(spanCount).toBeGreaterThan(0);

    // Set invalid language preference (e.g., "xyz")
    const invalidOption = page.getByRole('option', { name: /xyz/i });
    await expect(invalidOption).toBeVisible();
    await invalidOption.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid language/i);
    await expect(errorMessage).toBeVisible();

    // Verify language dropdown is still visible
    await expect(languageDropdown).toBeVisible();

    // Verify default language is still selected
    await expect(defaultLanguageLabel).toBeVisible();

    // Verify user can clear the invalid selection
    const clearButton = page.getByRole('button', { name: /clear/i });
    await expect(clearButton).toBeVisible();
    await clearButton.click();

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify default language is selected again
    await expect(defaultLanguageLabel).toBeVisible();
  });
});
